// Generated by Rangular from CounterComponent (app-counter). Do not edit by hand.
import { useState } from 'react';
import { RgAppbar, RgButton, RgScreen, RgText } from '@rangular/ui';

export default function Counter() {
  const [count, setCount] = useState(0);
  const increment = () => {
    setCount(count + 1);
  };
  const decrement = () => {
    setCount(count - 1);
  };
  const reset = () => {
    setCount(0);
  };
  return (
    <RgScreen>
      <RgAppbar title="Counter" />
      <RgText variant="display">{count}</RgText>
      {(count >= 5) && (
        <RgText variant="bodyLarge">Past five. Keep going</RgText>
      )}
      <RgButton onPress={() => increment()}>Increment</RgButton>
      <RgButton disabled={(count === 0)} onPress={() => decrement()}>Decrement</RgButton>
      <RgButton onPress={() => reset()}>Reset</RgButton>
    </RgScreen>
  );
}
